{
  "questions": [
    {
      "label": "Where are you seeking help?",
      "options": [
        "Pharmacy",
        "Hospital or clinic",
        "Speaking with a hotel receptionist",
        "Talking to a friend or coworker"
      ]
    },
    {
      "label": "What kind of symptoms do you have?",
      "options": [
        "Cold, flu, or fever",
        "Stomach or digestive issues",
        "Pain or injury",
        "Allergic reaction or rash"
      ]
    },
    {
      "label": "How severe is the situation?",
      "options": [
        "Mild discomfort",
        "Moderate, need specific medicine",
        "Severe, urgent medical care needed"
      ]
    }
  ],
  "checklist": [
    {
      "label": "Describe my symptoms",
      "checked": true
    },
    {
      "label": "Ask about medication",
      "checked": true
    },
    {
      "label": "Explain allergies",
      "checked": true
    },
    {
      "label": "Ask for the doctor or clinic",
      "checked": true
    },
    {
      "label": "Discuss payment and insurance",
      "checked": false
    },
    {
      "label": "Ask for a sick leave note",
      "checked": false
    }
  ]
}
